mapper.select:
select l.`id`, l.`device_name` as deviceName, l.`request_ip` as requestIp, l.`conversation_type` as conversationType, latest.`conversation_content` as conversationContent, l.`conversation_result` as conversationResult, l.`model`, l.`stream`, l.`success`, l.`elapsed_ms` as elapsedMs, l.`gmt_create` as gmtCreate from ai_conversation_log l inner join ( select max(id) as id, group_concat(conversation_content order by id separator '\n') as conversation_content from ai_conversation_log
and device_name like concat('%', #{deviceName}, '%')
and conversation_type = #{conversationType}
and conversation_content like concat('%', #{conversationContent}, '%')
and success = #{success}
group by ifnull(nullif(device_name, ''), concat('UNKNOWN-', request_ip)) ) latest on l.id = latest.id
and l.device_name like concat('%', #{deviceName}, '%')
and l.conversation_type = #{conversationType}
and l.conversation_content like concat('%', #{conversationContent}, '%')
and l.success = #{success}
order by l.${sort} ${order}
order by l.id desc
limit #{offset}, #{limit}

select count(*) from (
    select ifnull(nullif(device_name, ''), concat('UNKNOWN-', request_ip)) as device_key
    from ai_conversation_log


            and device_name like concat('%', #{deviceName}, '%')


            and conversation_type = #{conversationType}


            and conversation_content like concat('%', #{conversationContent}, '%')


            and success = #{success}


    group by ifnull(nullif(device_name, ''), concat('UNKNOWN-', request_ip))
) t
